"""Convert a post to safe HTML, quote any HTML code, convert
    URLs to live links and spot any @mentions or #tags and turn
    them into links.  Return the HTML string"""
def post_to_html(content: Any) -> object {
    content = content.replace("&", "&amp;");
    content = content.replace("<", "&lt;");
    content = content.replace(">", "&gt;");
    import re;
    r = re.compile(r"(http://[^ ]+)");
    return r.sub(r'<a href="\1">\1</a>', content);
    return content;
}

"""Calculate the nth fibonacci number using the seeds a and b"""
def fib1(a: Any, b: Any, n: Any) -> object {
    if (n == 1) {
        return a;
    } elif (n == 2) {
        return b;
    } else {
        return (fib1(a, b, (n - 1)) + fib1(a, b, (n - 2)));
    }
}

